same_round_only.sql:
INSERT INTO claim_evidence(claim_id,evidence_id,program_id,round_id)
SELECT c.claim_id,e.evidence_id,c.program_id,c.round_id FROM claim c JOIN evidence e USING(program_id)
WHERE e.round_id IS NULL ORDER BY c.claim_id,e.evidence_id LIMIT 1;

pattern_source_role_mismatch.sql:
SELECT count(*) FROM pattern_evidence pe JOIN evidence e USING(evidence_id)
WHERE (pe.purpose='case_observation' AND pe.case_document_role<>e.source_role)
  OR (pe.purpose<>'case_observation' AND e.source_role NOT IN ('official_notice','official_guideline','official_form'));
